export default class PickleUtils{p=null;constructor(e){this.p=e}generateID(){return`pckl-${this.p.constructor.instances.size+1}-${Math.random().toString(16).slice(2,8)}`}getElement(e){if("string"==typeof e){e.startsWith("#")&&(e=e.slice(1));const t=document.getElementById(e);return t instanceof HTMLSelectElement?t:null}return e instanceof HTMLSelectElement?e:null}escapeRegExp(e){return e.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}log(e="log",...t){if(this.p.debug){const r="color: #33a383; font-weight: bold;";switch(e){case"info":return void console.info("%c[Pickle]",r,...t);case"warn":return void console.warn("%c[Pickle]",r,...t);case"error":return void console.error("%c[Pickle]",r,...t);default:return void console.log("%c[Pickle]",r,...t)}}}closeOtherInstances(){this.p.constructor.instances.forEach((e=>{e!==this.p&&e.isOpen&&e.close()}))}getOnChange(e){if(e&&"function"!=typeof e)throw this.p.debug&&this.p.utils.log("error","onChange must be a function"),new Error("onChange must be a function",{cause:new Error("Invalid onChange callback")});return e}getDefaultValue(e){if(null===e)return null;if("string"==typeof e)return e;if(this.p.isMultiple&&Array.isArray(e))return e.every((e=>"string"==typeof e))?e:[];throw this.p.debug&&this.p.utils.log("error","defaultValue must be a string or an array of strings"),new Error("defaultValue must be a string or an array of strings",{cause:new Error("Invalid defaultValue")})}}